cypress_script:
describe('Todo List Functionality', () => {
  it('should add a new todo item', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('input[data-testid="text-input"]').type('New Todo Item{enter}');
    cy.get('ul[data-testid="todo-list"]').should('contain', 'New Todo Item');
  });

  it('should not add a todo when the input is empty', () => {
    cy.visit('https://todomvc.com/examples/react/dist/');
    cy.get('input[data-testid="text-input"]').clear().type('{enter}');
    cy.url().should('eq', 'https://todomvc.com/examples/react/dist/');
    cy.get('ul[data-testid="todo-list"]').should('not.contain', '');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Todo List Functionality', () => {
  test('should add a new todo item', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('input[data-testid="text-input"]', 'New Todo Item');
    await page.keyboard.press('Enter');
    await expect(page.locator('ul[data-testid="todo-list"]').locator('text=New Todo Item')).toBeVisible();
  });

  test('should not add a todo when the input is empty', async ({ page }) => {
    await page.goto('https://todomvc.com/examples/react/dist/');
    await page.fill('input[data-testid="text-input"]', '');
    await page.keyboard.press('Enter');
    await expect(page).toHaveURL('https://todomvc.com/examples/react/dist/');
    await expect(page.locator('ul[data-testid="todo-list"]').locator('text=')).not.toBeVisible();
  });
});
